# The step-1 GRM genotype store, checked against an INDEPENDENT decode of the
# same .bed.
#
# This is the gate that LEDGER #53/#56 slipped through. Every step-0 and step-1
# golden was byte-REPRODUCIBLE while encoding, for samples 1-4 of every marker,
# genotypes that are not the ones in the .bed: the re-packer's first
# accumulation byte was read uninitialised (`unsigned char geno2;` +
# `setGenotype`'s `|=`). Reproducibility is not correctness, and no golden could
# see this because every golden was generated by the same packer.
#
# Two assertions, deliberately independent of each other:
#   1. the decoded store equals a plain readBin decode of the .bed;
#   2. the store's own genotypes reproduce getAlleleFreqVec().
# (2) alone would have caught the bug without any external decoder, because the
# allele counts are computed BEFORE the repack, from the unpacked temporary --
# so the frequencies stayed right while the packed bytes went wrong.

test_that("the GRM genotype store matches an independent .bed decode", {
  skip_unless_level("standard")

  base <- file.path(saige_extdata, "input", "genotype_100markers")

  # setgeno populates a C++ global, so it is driven in a child process.
  out <- tempfile(fileext = ".rds")
  script <- tempfile(fileext = ".R")
  writeLines(c(
    "suppressPackageStartupMessages(library(SAIGE))",
    sprintf('base <- "%s"; out <- "%s"', base, out),
    "setminMAFforGRM(0.01); setmaxMissingRateforGRM(0.15)",
    'ids <- SAIGE:::readGenoSampleIDs("plink", famFile = paste0(base, ".fam"))',
    "n <- length(ids)",
    'setgeno(paste0(base, ".bed"), paste0(base, ".bim"), paste0(base, ".fam"),',
    "        seq_len(n), rep(TRUE, n), 2, FALSE)",
    # gettotalMarker() is the marker count in the FILE; the store holds the
    # QC-passing ones, which is what getAlleleFreqVec() is indexed by.
    "M <- sum(getQCdMarkerIndex())",
    "saveRDS(list(N = getNnomissingOut(), M = M, qcd = getQCdMarkerIndex(),",
    "             freq = getAlleleFreqVec(),",
    "             g = sapply(seq_len(M) - 1L, function(i) Get_OneSNP_Geno(i))),",
    "        out)"
  ), script)
  st <- suppressWarnings(system2(file.path(R.home("bin"), "Rscript"), script,
                                 stdout = FALSE, stderr = FALSE))
  expect_identical(as.integer(st), 0L)
  s <- readRDS(out)

  keep <- which(s$qcd)
  expect_identical(length(keep), s$M)
  expect_gt(s$M, 0L)

  # --- independent decode -------------------------------------------------
  # plink1 .bed, variant-major, 2 bits per sample, LSB-first within a byte.
  # Codes: 00 hom-A1, 01 missing, 10 het, 11 hom-A2. Step 1 counts copies of
  # bim column 5 (A1 under alt-first), so 00 -> 2, 10 -> 1, 11 -> 0.
  code2alt <- c(2L, NA_integer_, 1L, 0L)
  nb <- ceiling(s$N / 4)
  con <- file(paste0(base, ".bed"), "rb")
  on.exit(close(con), add = TRUE)
  expect_identical(readBin(con, "raw", 3L), as.raw(c(0x6c, 0x1b, 0x01)))

  readMarker <- function(m) {
    seek(con, 3 + (m - 1) * nb)
    bi <- as.integer(readBin(con, "raw", nb))
    out <- integer(nb * 4L)
    for (u in 0:3) {
      out[seq(u + 1L, nb * 4L, by = 4L)] <- bitwAnd(bitwShiftR(bi, 2L * u), 3L)
    }
    code2alt[out[seq_len(s$N)] + 1L]
  }

  mismatches <- 0L
  checked <- 0L
  for (k in seq_len(s$M)) {
    expected <- readMarker(keep[k])
    observed <- s$g[, k]
    # Missing calls are imputed to round(2*altFreq) at ingest; the imputed value
    # is exercised elsewhere, so only observed calls are compared here.
    nm <- !is.na(expected)
    checked <- checked + sum(nm)
    mismatches <- mismatches + sum(expected[nm] != observed[nm])
  }
  expect_gt(checked, 0L)
  expect_identical(mismatches, 0L)

  # --- self-consistency, no external decoder -------------------------------
  # getAlleleFreqVec() is computed before the repack; the store is the repack.
  freqFromStore <- colSums(s$g) / (2 * s$N)
  expect_equal(as.numeric(s$freq), freqFromStore, tolerance = 1e-6)
})
